const CINES = [
  { id: 'cc', nombre: 'Cine Colombia', host: 'cinecolombia.com', base: 'https://www.cinecolombia.com', urls: ['https://www.cinecolombia.com/cali/cartelera', 'https://www.cinecolombia.com/cali/peliculas', 'https://www.cinecolombia.com/cali', 'https://www.cinecolombia.com/'] },
  { id: 'cp', nombre: 'Cinépolis', host: 'cinepolis.com.co', base: 'https://cinepolis.com.co', urls: ['https://cinepolis.com.co/cartelera/cali-colombia', 'https://cinepolis.com.co/cartelera'] },
  { id: 'cm', nombre: 'Cinemark', host: 'cinemark.com.co', base: 'https://www.cinemark.com.co', urls: ['https://www.cinemark.com.co/ciudad/cali', 'https://www.cinemark.com.co/cartelera/cali', 'https://www.cinemark.com.co/'] }
];
const norm = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
// la misma película se llama distinto en cada cine («Spider-Man 2D», «Spider-Man (Doblada)»): se quita lo que no es el nombre
const claveTitulo = (t) => norm(t).replace(/\((dob|sub|doblada|subtitulada|2d|3d|4dx|vip)[^)]*\)/g, ' ').replace(/\b(2d|3d|4dx|vip|imax|dob|sub|doblada|subtitulada|screenx|macro xe)\b/g, ' ').replace(/[^a-z0-9]+/g, '');

// Cine de Cali leído DIRECTO de las páginas de Cine Colombia, Cinépolis y Cinemark (la IA solo ayuda a entender el texto de cada página).
// cartelera → películas de los 3 cines · horarios → funciones de una película en cada cine · calificar → puntajes y si encaja · opinion → ¿vale la pena?
const it = $input.first().json;
let b = it.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
if (b.token !== 'mercado-7d41c2a9e05b') return [{ json: { listo: true, respuesta: { ok: false, error: 'token' } } }];
const MODELO = 'claude-haiku-4-5-20251001';
const sd = $getWorkflowStaticData('global');
sd.cache = sd.cache || {}; sd.trab = sd.trab || {}; sd.err = sd.err || {};
const accion = ['cartelera', 'horarios', 'calificar', 'opinion', 'clave'].includes(b.accion) ? b.accion : 'cartelera';
// clave gratis de TMDB (themoviedb.org): da la lista de películas en cartelera en Colombia con sus pósters y puntajes
if (accion === 'clave') {
  const k = String(b.clave || '').trim();
  sd.tmdb = /^[A-Za-z0-9]{16,64}$/.test(k) || /^[A-Za-z0-9._-]{40,500}$/.test(k) ? k : '';
  Object.keys(sd.cache).filter(x => x.startsWith('cartelera')).forEach(x => delete sd.cache[x]);
  return [{ json: { listo: true, respuesta: { ok: true, conClave: !!sd.tmdb } } }];
}
const co = new Date(Date.now() - 5 * 3600 * 1000);
const hoy = co.toISOString().slice(0, 10);
const limpia = (t) => String(t || '').replace(/[<>{}\[\]\n\r"]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 90);
const titulo = limpia(b.titulo);
const fecha = /^\d{4}-\d{2}-\d{2}$/.test(String(b.fecha || '')) ? b.fecha : hoy;
if ((accion === 'horarios' || accion === 'opinion') && !titulo) return [{ json: { listo: true, respuesta: { ok: false, error: 'titulo' } } }];
// solo se leen páginas de los 3 cines (nada de direcciones arbitrarias)
const urls = {};
if (b.urls && typeof b.urls === 'object') CINES.forEach(c => { try { const u = new URL(String(b.urls[c.id] || '')); if (u.protocol === 'https:' && (u.hostname === c.host || u.hostname.endsWith('.' + c.host))) urls[c.id] = u.href.slice(0, 300); } catch (e) {} });
const conocidos = (Array.isArray(b.cines) ? b.cines : []).filter(x => CINES.some(c => c.id === x));
const titulos = (Array.isArray(b.titulos) ? b.titulos : []).map(limpia).filter(Boolean).slice(0, 20);
if (accion === 'calificar' && !titulos.length) return [{ json: { listo: true, respuesta: { ok: false, error: 'titulos' } } }];

const TTL = { cartelera: 6, horarios: 2, calificar: 24, opinion: 24 };
const mes = hoy.slice(0, 7);
const hash = (t) => { let h = 0; for (const c of t) h = (h * 31 + c.charCodeAt(0)) >>> 0; return h.toString(36); };
const clave = accion === 'cartelera' ? 'cartelera|' + hoy : accion === 'calificar' ? 'calificar|' + mes + '|' + hash(titulos.map(claveTitulo).sort().join(',')) : accion === 'horarios' ? 'horarios|' + claveTitulo(titulo) + '|' + fecha : 'opinion|' + claveTitulo(titulo);
// si la búsqueda anterior falló, se le cuenta a la app (con el motivo) una sola vez
if (sd.err[clave]) { const e = sd.err[clave]; delete sd.err[clave]; if (Date.now() - e.t < 300000) return [{ json: { listo: true, respuesta: { ok: false, error: 'ia', detalle: e.msg } } }]; }
const c = sd.cache[clave];
if (c && !b.forzar && Date.now() - c.t < TTL[accion] * 3600 * 1000) return [{ json: { listo: true, respuesta: Object.assign({}, c.v, { enCache: true }) } }];
// si ya hay una en marcha para esto, la app solo espera (no se repite ni se gasta de más)
if (sd.trab[clave] && Date.now() - sd.trab[clave] < 200000) return [{ json: { listo: true, respuesta: { ok: true, pendiente: true } } }];

const PERFIL = 'La familia son una pareja adulta con un hijo pequeño (Ema) en Cali. Les gusta el suspenso y los thrillers bien hechos (como «Perdida»), la acción si de verdad es buena, y las películas con buena crítica. No les gusta el terror ni el anime violento (como «Demon Slayer»).';
const SISTEMA = 'Eres Armoni, el asistente de una familia de Cali (Colombia). Nunca inventes películas, horarios ni puntajes: si no lo encuentras, déjalo vacío o en null. Responde SOLO con un JSON válido, sin texto adicional ni comillas dobles dentro de los textos.';
let peticion = null;
if (accion === 'calificar' || accion === 'opinion') {
  const prompt = accion === 'calificar'
    ? 'Hoy es ' + hoy + '. Estas películas están en cartelera en Cali: ' + titulos.join(' | ') + '. Busca en la web datos de cada una. ' + PERFIL + ' Para cada una da: titulo (igual al que te di), generos (lista corta en español), duracion (minutos o null), clasificacion (edad o null), sinopsis (una frase corta), score (puntaje de críticos de 0 a 100 de Rotten Tomatoes, Metacritic o IMDb convertido, o null), fuente, encaja ("si", "tal vez" o "no" según el perfil) y porque (una frase corta). Formato: {"peliculas":[{"titulo":"","generos":[],"duracion":null,"clasificacion":null,"sinopsis":"","score":null,"fuente":"","encaja":"tal vez","porque":""}]}'
    : 'Hoy es ' + hoy + '. Dime si vale la pena ir a ver al cine «' + titulo + '». Busca reseñas de críticos, el puntaje del público y lo que se dice en redes y medios. ' + PERFIL + ' Distingue el ruido de la calidad: una película de la que se habla mucho solo vale la pena si además las críticas o el público la respaldan, o si superó las expectativas. Veredicto: "vale" solo si hay conversación fuerte Y la calidad lo respalda (o superó expectativas); "esperar" si hay mucho ruido pero la calidad es dudosa o aún no hay reseñas suficientes; "no" si las críticas son malas o no encaja con la familia. Formato: {"veredicto":"esperar","titular":"frase corta","resumen":"dos frases","razones":["","",""],"critica":{"score":null,"fuente":""},"publico":{"score":null,"fuente":""},"buzz":"alto|medio|bajo","superoExpectativas":false}';
  peticion = { model: MODELO, max_tokens: 4000, system: SISTEMA, tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 4 }], messages: [{ role: 'user', content: prompt }] };
}
sd.trab[clave] = Date.now();
return [{ json: { listo: false, accion, clave, titulo, fecha, urls, conocidos, peticion, hoy } }];

const CINES = [
  { id: 'cc', nombre: 'Cine Colombia', host: 'cinecolombia.com', base: 'https://www.cinecolombia.com', urls: ['https://www.cinecolombia.com/cali/cartelera', 'https://www.cinecolombia.com/cali/peliculas', 'https://www.cinecolombia.com/cali', 'https://www.cinecolombia.com/'] },
  { id: 'cp', nombre: 'Cinépolis', host: 'cinepolis.com.co', base: 'https://cinepolis.com.co', urls: ['https://cinepolis.com.co/cartelera/cali-colombia', 'https://cinepolis.com.co/cartelera'] },
  { id: 'cm', nombre: 'Cinemark', host: 'cinemark.com.co', base: 'https://www.cinemark.com.co', urls: ['https://www.cinemark.com.co/ciudad/cali', 'https://www.cinemark.com.co/cartelera/cali', 'https://www.cinemark.com.co/'] }
];
const norm = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
// la misma película se llama distinto en cada cine («Spider-Man 2D», «Spider-Man (Doblada)»): se quita lo que no es el nombre
const claveTitulo = (t) => norm(t).replace(/\((dob|sub|doblada|subtitulada|2d|3d|4dx|vip)[^)]*\)/g, ' ').replace(/\b(2d|3d|4dx|vip|imax|dob|sub|doblada|subtitulada|screenx|macro xe)\b/g, ' ').replace(/[^a-z0-9]+/g, '');

const http = (o) => this.helpers.httpRequest(o);
// Lee lo que sacó la IA, lo limpia, junta los 3 cines y lo guarda un rato.
const v = $('Validar').first().json;
const sd = $getWorkflowStaticData('global');
sd.cache = sd.cache || {}; sd.trab = sd.trab || {}; sd.err = sd.err || {};
const r = $input.first().json;
delete sd.trab[v.clave];
const falla = (msg) => { sd.err[v.clave] = { t: Date.now(), msg: String(msg).slice(0, 300) }; return [{ json: { respuesta: { ok: false } } }]; };
if (r.error || !Array.isArray(r.content)) return falla((r.error && (r.error.message || r.error)) || r.message || 'sin respuesta de la IA');
const texto = r.content.filter(x => x.type === 'text').map(x => x.text).join('\n');
const m = texto.match(/\{[\s\S]*\}/);
let out = null;
try { out = JSON.parse(m ? m[0] : texto); } catch (e) {}
if (!out) return falla('La IA no devolvió datos legibles');
const txt = (t, n) => String(t == null ? '' : t).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n || 200);
const num = (x) => { const n = Number(x); return isFinite(n) && x !== null && x !== '' ? Math.max(0, Math.min(100, Math.round(n))) : null; };
const absoluta = (u, base) => { try { const x = new URL(String(u || '').trim(), base); return /^https?:$/.test(x.protocol) ? x.href.slice(0, 400) : null; } catch (e) { return null; } };
let respuesta;

if (v.accion === 'cartelera') {
  const mapa = {};
  (Array.isArray(out.cines) ? out.cines : []).forEach(cx => {
    const c = CINES.find(k => k.id === cx.id); if (!c) return;
    (Array.isArray(cx.peliculas) ? cx.peliculas : []).slice(0, 40).forEach(p => {
      const titulo = txt(p.titulo, 90); const k = claveTitulo(titulo); if (!titulo || !k) return;
      const e = mapa[k] = mapa[k] || { clave: k, titulo, poster: null, cines: [], urls: {} };
      if (!e.cines.includes(c.id)) e.cines.push(c.id);
      const u = absoluta(p.url, c.base); if (u && !e.urls[c.id]) e.urls[c.id] = u;
      const po = absoluta(p.poster, c.base); if (po && !e.poster) e.poster = po;
      if (titulo.length < e.titulo.length) e.titulo = titulo;
    });
  });
  let pelis = Object.values(mapa).sort((a, b) => b.cines.length - a.cines.length || a.titulo.localeCompare(b.titulo)).slice(0, 40);
  // TMDB: películas en cartelera en Colombia, con póster, puntaje y géneros (no se bloquea como las páginas de los cines)
  let tmdbError = '';
  if (sd.tmdb) {
    const GEN = { 28: 'Acción', 12: 'Aventura', 16: 'Animación', 35: 'Comedia', 80: 'Crimen', 99: 'Documental', 18: 'Drama', 10751: 'Familiar', 14: 'Fantasía', 36: 'Historia', 27: 'Terror', 10402: 'Música', 9648: 'Misterio', 10749: 'Romance', 878: 'Ciencia ficción', 53: 'Suspenso', 10752: 'Guerra', 37: 'Western' };
    const jwt = sd.tmdb.includes('.') || sd.tmdb.length > 40;
    let lista = [];
    try {
      for (const pg of [1, 2]) { const res = await http({ method: 'GET', url: 'https://api.themoviedb.org/3/movie/now_playing?region=CO&language=es-CO&page=' + pg + (jwt ? '' : '&api_key=' + sd.tmdb), headers: jwt ? { Authorization: 'Bearer ' + sd.tmdb } : {}, json: true, timeout: 15000 }); lista = lista.concat((res && res.results) || []); }
    } catch (e) { tmdbError = String(e.message || e).slice(0, 100); }
    const poster = (x) => x.poster_path ? 'https://image.tmdb.org/t/p/w342' + x.poster_path : null;
    const porClave = {}; lista.forEach(x => { [x.title, x.original_title].forEach(t => { const k = claveTitulo(t); if (k && !porClave[k]) porClave[k] = x; }); });
    const ficha = (p, x) => { p.poster = poster(x) || p.poster; if (x.vote_count > 20 && x.vote_average > 0) { p.score = Math.round(x.vote_average * 10); p.fuente = 'TMDB'; } p.generos = (x.genre_ids || []).map(g => GEN[g]).filter(Boolean).slice(0, 3); if (x.overview) p.sinopsis = txt(x.overview, 220); p.estreno = x.release_date || null; p.tmdb = true; };
    const usados = {};
    pelis.forEach(p => { const x = porClave[p.clave]; if (x) { ficha(p, x); usados[x.id] = 1; } });
    // si los cines casi no se pudieron leer, se muestra igual la cartelera de Colombia (sin saber en qué cine)
    if (pelis.length < 6) lista.filter(x => !usados[x.id] && poster(x)).sort((a, b) => b.popularity - a.popularity).slice(0, 24).forEach(x => { const t = txt(x.title, 90); const k = claveTitulo(t); if (!k || pelis.some(p => p.clave === k)) return; const p = { clave: k, titulo: t, poster: null, cines: [], urls: {} }; ficha(p, x); pelis.push(p); });
  }
  const diag = (sd.diagClave === v.clave ? sd.diag : null) || [];
  const dg = (c) => diag.find(x => x.id === c.id) || {};
  const porCine = CINES.map(c => { const x = dg(c); const n = pelis.filter(p => p.cines.includes(c.id)).length; return { id: c.id, cine: c.nombre, peliculas: n, leida: !!x.leida, http: x.http || 0, error: x.error || '', via: x.via === 'jina' ? 'lectura' : (x.via || ''), causa: n ? 'ok' : (x.leida ? 'ia_sin_peliculas' : (x.causa || 'sin_diag')), candidatos: x.candidatos || 0, directa: x.directa || 0, lectura: x.lectura || 0, intentos: x.intentos || [], muestra: x.muestra || [], inicio: x.inicio || '' }; });
  if (!pelis.length) return falla('No pude leer ninguna película. ' + porCine.map(x => x.cine + ': ' + x.causa + (x.http ? ' (HTTP ' + x.http + ')' : '') + (x.error ? ' ' + x.error : '')).join(' · '));
  respuesta = { ok: true, conClave: !!sd.tmdb, tmdbError, peliculas: pelis.map(p => ({ id: p.clave, clave: p.clave, titulo: p.titulo, poster: p.poster, cines: p.cines, urls: p.urls, generos: p.generos, score: p.score == null ? null : p.score, fuente: p.fuente, sinopsis: p.sinopsis, estreno: p.estreno })), porCine, actualizado: new Date().toISOString() };
} else if (v.accion === 'horarios') {
  const diagH = sd.diagH || [];
  const cines = CINES.map(c => {
    const cx = (Array.isArray(out.cines) ? out.cines : []).find(x => x.id === c.id) || {};
    const sedes = (Array.isArray(cx.sedes) ? cx.sedes : []).slice(0, 8).map(s => ({ sede: txt(s.sede, 50), horarios: (Array.isArray(s.horarios) ? s.horarios : []).filter(h => /^\d{1,2}:\d{2}$/.test(String(h.hora || ''))).slice(0, 14).map(h => ({ hora: String(h.hora).padStart(5, '0'), formato: txt(h.formato, 12), idioma: txt(h.idioma, 14) })) })).filter(s => s.sede && s.horarios.length);
    const url = (v.urls && v.urls[c.id]) || null;
    const d = diagH.find(x => x.id === c.id);
    const conocido = (v.conocidas || v.conocidos || []).length > 0;
    const estado = !url ? (conocido ? 'no_esta' : 'sin_enlace') : sedes.length ? 'ok' : (d && !d.leida) ? 'no_leida' : 'sin_horarios';
    return { id: c.id, cine: c.nombre, url: url || c.urls[0], estado, sedes, nota: txt(cx.nota, 140) };
  });
  respuesta = { ok: true, titulo: v.titulo, fecha: v.fecha, cines, actualizado: new Date().toISOString() };
} else if (v.accion === 'calificar') {
  const datos = {};
  (Array.isArray(out.peliculas) ? out.peliculas : []).forEach(p => {
    const k = claveTitulo(p.titulo); if (!k) return;
    datos[k] = { generos: (Array.isArray(p.generos) ? p.generos : []).slice(0, 3).map(g => txt(g, 24)), duracion: Number(p.duracion) > 0 ? Math.round(Number(p.duracion)) : null, clasificacion: txt(p.clasificacion, 12) || null, sinopsis: txt(p.sinopsis, 220), score: num(p.score), fuente: txt(p.fuente, 30), encaja: ['si', 'tal vez', 'no'].includes(p.encaja) ? p.encaja : 'tal vez', porque: txt(p.porque, 140) };
  });
  respuesta = { ok: true, datos, actualizado: new Date().toISOString() };
} else {
  const sc = (o) => ({ score: num(o && o.score), fuente: txt(o && o.fuente, 30) });
  respuesta = { ok: true, titulo: v.titulo, veredicto: ['vale', 'esperar', 'no'].includes(out.veredicto) ? out.veredicto : 'esperar', titular: txt(out.titular, 120), resumen: txt(out.resumen, 320),
    razones: (Array.isArray(out.razones) ? out.razones : []).slice(0, 3).map(x => txt(x, 140)).filter(Boolean), critica: sc(out.critica), publico: sc(out.publico),
    buzz: ['alto', 'medio', 'bajo'].includes(out.buzz) ? out.buzz : 'medio', superoExpectativas: !!out.superoExpectativas, actualizado: new Date().toISOString() };
}
sd.cache[v.clave] = { t: Date.now(), v: respuesta };
const ks = Object.keys(sd.cache);
if (ks.length > 80) ks.sort((a, b) => sd.cache[a].t - sd.cache[b].t).slice(0, ks.length - 80).forEach(k => delete sd.cache[k]);
return [{ json: { respuesta } }];

// Entra a las páginas de los cines (desde tu computador) y le da a la IA lo que encontró para que saque las películas o los horarios.
// 1) lectura directa de la página: películas desde el JSON embebido y las tarjetas
// 2) si no trae películas (página que se arma con JavaScript, o que bloquea lecturas automáticas): lectura renderizada con r.jina.ai (solo se le pasa la dirección pública del cine)
const http = (o) => this.helpers.httpRequest(o);
const CINES = [
  { id: 'cc', nombre: 'Cine Colombia', host: 'cinecolombia.com', base: 'https://www.cinecolombia.com', urls: ['https://www.cinecolombia.com/cali/cartelera', 'https://www.cinecolombia.com/cali/peliculas', 'https://www.cinecolombia.com/cali', 'https://www.cinecolombia.com/'] },
  { id: 'cp', nombre: 'Cinépolis', host: 'cinepolis.com.co', base: 'https://cinepolis.com.co', urls: ['https://cinepolis.com.co/cartelera/cali-colombia', 'https://cinepolis.com.co/cartelera'] },
  { id: 'cm', nombre: 'Cinemark', host: 'cinemark.com.co', base: 'https://www.cinemark.com.co', urls: ['https://www.cinemark.com.co/ciudad/cali', 'https://www.cinemark.com.co/cartelera/cali', 'https://www.cinemark.com.co/'] }
];
const norm = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const claveTitulo = (t) => norm(t).replace(/[^a-z0-9]+/g, '');
const v = $('Validar').first().json;
const sd = $getWorkflowStaticData('global');
if (v.peticion) return [{ json: v }];                  // calificar y opinion ya traen su petición
const MODELO = 'claude-haiku-4-5-20251001';
const H = { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', 'Accept': 'text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8', 'Accept-Language': 'es-CO,es;q=0.9' };
// Extractor de películas (e2): JSON embebido + tarjetas HTML (árbol DOM ligero) + markdown. Sin dependencias.
const ENT = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó', uacute: 'ú', Aacute: 'Á', Eacute: 'É', Iacute: 'Í', Oacute: 'Ó', Uacute: 'Ú', ntilde: 'ñ', Ntilde: 'Ñ', uuml: 'ü', Uuml: 'Ü', iexcl: '¡', iquest: '¿', agrave: 'à', egrave: 'è', igrave: 'ì', ograve: 'ò', ugrave: 'ù', acirc: 'â', ecirc: 'ê', ocirc: 'ô', ccedil: 'ç', Ccedil: 'Ç', auml: 'ä', euml: 'ë', ouml: 'ö', laquo: '«', raquo: '»', ndash: '–', mdash: '—', hellip: '…', lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', middot: '·', deg: '°', ordf: 'ª', ordm: 'º', copy: '©', reg: '®', trade: '™' };
const decode1 = (s) => s.replace(/&(#x[0-9a-f]+|#\d+|[a-z][a-z0-9]*);/gi, (m, e) => {
  if (e[0] === '#') { const n = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10); try { return String.fromCodePoint(n); } catch (x) { return m; } }
  return Object.prototype.hasOwnProperty.call(ENT, e) ? ENT[e] : m;
});
